import pytest

from bedrock_protocol import v975, v1001, v2168

EMPTY_ITEM_BLOB = "\x00" * 10

# generated by gophertunnel 6353c49:
# packet.CreativeContent{
#   Groups: []protocol.CreativeGroup{{Category: protocol.CreativeCategoryNature, Name: "itemGroup.name.planks",
#     Icon: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 7}, Count: 4, BlockRuntimeID: 9}}},
#   Items: []protocol.CreativeItem{{CreativeItemNetworkID: 1,
#     Item: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 7}, Count: 4, BlockRuntimeID: 9},
#     GroupIndex: 0}}}
V1001 = bytes.fromhex(
    "0102000000156974656d47726f75702e6e616d652e706c616e6b730e040000120a0000000000000000000001010e040000120a0000000000000000000000"
)

# generated by gophertunnel b8bd735:
# packet.CreativeContent{
#   Groups: []protocol.CreativeGroup{{Category: protocol.CreativeCategoryNature, Name: "itemGroup.name.planks",
#     Icon: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 7}, Count: 4, BlockRuntimeID: 9}}},
#   Items: []protocol.CreativeItem{{CreativeItemNetworkID: 1,
#     Item: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 7}, Count: 4, BlockRuntimeID: 9},
#     GroupIndex: 0}}}
V2168 = bytes.fromhex(
    "0102156974656d47726f75702e6e616d652e706c616e6b730e040000120a0000000000000000000001010e040000120a0000000000000000000000"
)

PLANK_V1001 = v1001.SerializedNetworkItemInstanceDescriptor(
    id=7, stack_size=4, block_runtime_id=9, user_data_buffer=EMPTY_ITEM_BLOB
)
PLANK_V2168 = v2168.SerializedNetworkItemInstanceDescriptor(
    id=7, stack_size=4, block_runtime_id=9, user_data_buffer=EMPTY_ITEM_BLOB
)

GOLDENS = [
    pytest.param(
        v1001.CreativeContentPacket(
            groups=[
                v1001.CreativeGroupInfoPayload(
                    creative_item_category=v1001.CreativeItemCategory.NATURE,
                    name="itemGroup.name.planks",
                    icon=PLANK_V1001,
                )
            ],
            entries=[
                v1001.CreativeItemEntryPayload(
                    creative_item_net_id=v1001.CreativeItemNetId(raw_id=1),
                    item_descriptor=PLANK_V1001,
                    group_index=0,
                )
            ],
        ),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v2168.CreativeContentPacket(
            groups=[
                v2168.CreativeGroupInfoPayload(
                    creative_item_category=v2168.CreativeItemCategory.NATURE,
                    name="itemGroup.name.planks",
                    icon=PLANK_V2168,
                )
            ],
            entries=[
                v2168.CreativeItemEntryPayload(
                    creative_item_net_id=v2168.CreativeItemNetId(raw_id=1),
                    item_descriptor=PLANK_V2168,
                    group_index=0,
                )
            ],
        ),
        V2168,
        id="v2168",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_creative_content_is_packet_145(version):
    assert version.PACKETS[145] is version.CreativeContentPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_creative_content_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_creative_content_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_creative_content_group_category_is_three_bytes_narrower_at_2168():
    assert len(V1001) == len(V2168) + 3


def test_creative_content_is_byte_identical_from_the_group_name_on():
    assert V1001[5:] == V2168[2:]
